import math

def calculate_factorial_and_print(n):
    """Calculates the factorial of a non-negative integer n, prints the result, and returns it.
    Returns None for invalid (negative or non-integer) inputs."""
    try:
        result = math.factorial(n)
    except (ValueError, TypeError):
        return None
    print(result)
    return result

